-- Custom migration scaffold generated by Drizzle.
-- Run with ordering writes paused. Unclassified drinks require an explicit operator-reviewed
-- category_v2 mapping after expansion; names/stations never imply alcohol content.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "public"."menu_items"
             WHERE category_v2 IS NULL AND category IS DISTINCT FROM 'food') THEN
    RAISE EXCEPTION 'Ordering migration: classify every legacy drink in menu_items.category_v2 as soft_drink or alcohol using an operator-reviewed mapping before retrying';
  END IF;
  IF EXISTS (SELECT 1 FROM "public"."order_items"
             GROUP BY order_id, menu_item_id HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'Ordering migration: duplicate legacy order/menu lines require operator review; no rows were merged or removed';
  END IF;
  IF EXISTS (SELECT 1 FROM "public"."order_items" WHERE quantity NOT BETWEEN 1 AND 100) THEN
    RAISE EXCEPTION 'Ordering migration: legacy quantity outside 1–100 requires operator review; no quantity was clipped';
  END IF;
END $$;
