UPDATE "public"."menu_items" SET category_v2 = 'meal'
WHERE category_v2 IS NULL AND category = 'food';
--> statement-breakpoint
INSERT INTO "public"."station_orders" (order_id, station, status, created_at, updated_at)
SELECT DISTINCT o.id, m.station,
  (CASE WHEN o.status::text = 'ready' THEN 'preparing' ELSE o.status::text END)::"public"."station_order_status",
  o.created_at, o.updated_at
FROM "public"."orders" o
JOIN "public"."order_items" i ON i.order_id = o.id
JOIN "public"."menu_items" m ON m.id = i.menu_item_id
ON CONFLICT (order_id, station) DO NOTHING;
--> statement-breakpoint
UPDATE "public"."order_items" i
SET station_order_id = s.id, quantity_limit = greatest(5, i.quantity)
FROM "public"."menu_items" m, "public"."station_orders" s
WHERE i.menu_item_id = m.id AND s.order_id = i.order_id AND s.station = m.station;
